const order = $input.first().json;
const event = $('Webhook · Đổi trạng thái').first().json.body;
const status = event.status;
const labels = {PENDING:'Chờ xác nhận',CONFIRMED:'Đã xác nhận',SHIPPING:'Đang giao',DELIVERED:'Đã giao',CANCELLED:'Đã hủy'};
if (!labels[status]) throw new Error('Trạng thái sự kiện không hợp lệ.');
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money = value => new Intl.NumberFormat('vi-VN', {style:'currency',currency:'VND'}).format(value);
const row = {code:order.code,createdAt:order.createdAt,customer:order.customerName,phone:order.phone,address:order.address,
  products:order.items.map(item => item.productName + ' · ' + item.color + ' / ' + item.size + ' / ' + item.gender + ' × ' + item.quantity + ' ' + item.unit).join('; '),
  quantity:order.items.reduce((sum,item) => sum+item.quantity,0),subtotal:order.subtotal,shippingFee:order.shippingFee,
  gender:order.items.map(item => item.gender).join('; '),packingFee:order.packingFee,
  hasLiveFish:order.hasLiveFish ? 'Có' : 'Không',preferredDelivery:order.preferredDelivery,deliveryNote:order.note + (order.couponCode ? ' | Mã ' + order.couponCode + ': giảm ' + ((order.discount || 0) + (order.shippingDiscount || 0)) + ' đ' : ''),
  total:order.total,paymentMethod:order.paymentMethod,paymentStatus:order.paymentStatus,status};
const site = ($env.SITE_URL || 'http://localhost:8080').replace(/\/+$/, '');
const url = site + '/track?code=' + encodeURIComponent(order.code);
const method = order.paymentMethod === 'BANK_QR' ?
  'Chuyển khoản đúng ' + money(order.total) + ', nội dung ' + order.code + (order.qrUrl ? '\nQR: ' + order.qrUrl : '') :
  'Thanh toán khi nhận hàng.';
const policy = order.hasLiveFish ? '\n' + order.doaPolicy : '';
const newText = 'Long Fish đã nhận đơn ' + order.code + '.\n' + row.products + '\nTổng: ' + money(order.total) + '.\n' + method;
const statusText = event.kind === 'payment' ? 'Long Fish · Đơn ' + order.code + ' · Đã nhận thanh toán ' + money(order.total) + '.' : 'Long Fish · Đơn ' + order.code + ' · ' + labels[status] + '.';
const htmlRows = order.items.map(item => '<tr><td>' + esc(item.productName) + '</td><td>' + esc(item.color) + ' / ' +
  esc(item.size) + ' / ' + esc(item.gender) + '</td><td>' + item.quantity + ' ' + esc(item.unit) + '</td><td>' + esc(money(item.unitPrice * item.quantity)) + '</td></tr>').join('');
const html = '<h2>Long Fish · Đơn mới ' + esc(order.code) + '</h2><p>' + esc(order.customerName) + ' · ' + esc(order.phone) +
  '<br>' + esc(order.address) + '</p><table border="1" cellpadding="8"><tr><th>Sản phẩm</th><th>Phân loại</th><th>SL</th><th>Tiền hàng</th></tr>' +
  htmlRows + '</table><p>Tiền hàng ' + money(order.subtotal) + ' · Giao hàng ' + money(order.shippingFee) + ' · Đóng gói ' + money(order.packingFee) +
  ' · Tổng ' + money(order.total) + '</p><p>' + esc(order.paymentMethod) + '</p><p>Cá sống: ' + row.hasLiveFish + '<br>Nhận mong muốn: ' +
  esc(order.preferredDelivery ? new Date(order.preferredDelivery).toLocaleString('vi-VN', {timeZone:'Asia/Ho_Chi_Minh'}) : '') +
  '<br>Ghi chú: ' + esc(order.note) + '</p>';
// --- Email gửi khách (thêm bởi scripts/n8n-customer-email.cjs) ---
const customerLabels = {CONFIRMED:'Đơn đã được xác nhận. Long Fish đang chuẩn bị hàng cho bạn.',
  SHIPPING:'Đơn đang được giao tới bạn.',DELIVERED:'Đơn đã được giao. Cảm ơn bạn đã mua hàng tại Long Fish.',
  CANCELLED:'Đơn đã được hủy. Nếu bạn không yêu cầu hủy, hãy trả lời email này hoặc nhắn Fanpage Long Fish.',
  PENDING:'Long Fish đã nhận đơn và sẽ xác nhận sớm.'};
const wantsEmail = !!order.email && !(event.kind === 'payment' && event.notify === false);
const customerEmail = wantsEmail ? String(order.email) : '';
const shell = (title, body) => '<div style="font-family:Arial,sans-serif;max-width:560px;color:#0e2a2b">' +
  '<div style="background:#1f5c46;padding:14px 18px;border-radius:12px 12px 0 0;margin-bottom:16px"><img src="' + site + '/logo-email.png" alt="Long Fish" width="40" height="40" style="vertical-align:middle;border:0">' +
  '<span style="color:#ffffff;font-size:20px;font-weight:bold;margin-left:10px;vertical-align:middle">Long Fish</span></div>' +
  '<h2 style="margin:0 0 12px">' + title + '</h2>' + body +
  '<p><a href="' + esc(url) + '" style="display:inline-block;background:#1f5c46;color:#fff;padding:10px 18px;border-radius:999px;text-decoration:none">Tra cứu đơn ' + esc(order.code) + '</a></p>' +
  '<p style="font-size:12px;color:#4a6661">Bạn nhận email này vì đã nhập địa chỉ email khi đặt hàng tại Long Fish. Email chỉ dùng cho thông báo đơn hàng.</p></div>';
const itemsTable = '<table cellpadding="6" style="border-collapse:collapse;width:100%;font-size:14px">' +
  order.items.map(item => '<tr style="border-bottom:1px solid #cfe2d8"><td>' + esc(item.productName) + '<br><small>' + esc(item.color) + ' / ' +
    esc(item.size) + ' / ' + esc(item.gender) + '</small></td><td>' + item.quantity + ' ' + esc(item.unit) + '</td><td style="text-align:right">' +
    esc(money(item.unitPrice * item.quantity)) + '</td></tr>').join('') + '</table>';
const totals = '<p>Tiền hàng ' + esc(money(order.subtotal)) +
  (order.discount ? '<br>Giảm giá (' + esc(order.couponCode) + ') -' + esc(money(order.discount)) : '') +
  (order.shippingDiscount ? '<br>Miễn phí vận chuyển (' + esc(order.couponCode) + ') -' + esc(money(order.shippingDiscount)) : '') +
  '<br>Giao hàng ' + esc(money(order.shippingFee)) +
  (order.packingFee ? '<br>Đóng gói cá sống ' + esc(money(order.packingFee)) : '') + '<br><strong>Tổng ' + esc(money(order.total)) + '</strong></p>';
const payHtml = order.paymentMethod === 'BANK_QR'
  ? '<p><strong>Chuyển khoản:</strong> đúng ' + esc(money(order.total)) + ', nội dung <strong>' + esc(order.code) + '</strong>.</p>' +
    (order.qrUrl ? '<p><img src="' + esc(order.qrUrl) + '" alt="Mã VietQR đơn ' + esc(order.code) + '" width="220"></p>' : '')
  : '<p><strong>Thanh toán:</strong> tiền mặt khi nhận hàng.</p>';
const policyHtml = order.hasLiveFish && order.doaPolicy ? '<p style="background:#eaf4ef;padding:10px;border-left:4px solid #f0642b">' + esc(order.doaPolicy) + '</p>' : '';
let customerSubject = '';
let customerHtml = '';
if (event.kind === 'created') {
  customerSubject = '[Long Fish] Xác nhận đơn ' + order.code;
  customerHtml = shell('Cảm ơn ' + esc(order.customerName) + ', Long Fish đã nhận đơn ' + esc(order.code),
    '<p>Giao tới: ' + esc(order.address) + '</p>' + itemsTable + totals + payHtml + policyHtml);
} else if (event.kind === 'payment') {
  customerSubject = '[Long Fish] Đã nhận thanh toán đơn ' + order.code;
  customerHtml = shell('Đã nhận thanh toán ' + esc(money(order.total)), '<p>Long Fish đã nhận tiền chuyển khoản cho đơn ' + esc(order.code) + '.</p>');
} else {
  customerSubject = '[Long Fish] Đơn ' + order.code + ': ' + labels[status];
  customerHtml = shell('Đơn ' + esc(order.code) + ': ' + esc(labels[status]), '<p>' + esc(customerLabels[status] || '') + '</p>' + (status === 'SHIPPING' ? policyHtml : ''));
}
return [{ json: {row, customerEmail, customerSubject, customerHtml, subject:'[Long Fish] Đơn mới ' + order.code, html, psid:order.psid,
  message:{text:(false ? newText.slice(0,1300) + policy : statusText + (status === 'SHIPPING' ? policy : '')) + '\nTra cứu: ' + url.toString()} } }];
